#!/bin/bash
# make_sha256sums.sh — regenerate SHA256SUMS over every shipped file.
#
# Covers all files in the pack except SHA256SUMS itself and the
# outputs/fresh-clone-* files: those are generated by clean_reproduce.sh
# AFTER the digest is made, and are verified by the comparison log instead
# (outputs/fresh-clone-compare.log). That exclusion is deliberate and
# documented here and in docs/methodology.md.
set -u
PACK_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$PACK_ROOT"
find . -type f \
  ! -name SHA256SUMS \
  ! -path './outputs/fresh-clone-*' \
  | sort | xargs sha256sum > SHA256SUMS
echo "SHA256SUMS written: $(wc -l < SHA256SUMS) files"
sha256sum SHA256SUMS
